const pageFilter=id=>{try{return JSON.parse(sessionStorage.getItem(`opsynq.dashboard.filter.${id}`)||'{}')||{}}catch{return{}}};
const clearPageAction=id=>{try{const key=`opsynq.dashboard.filter.${id}`,value=pageFilter(id);if(value.action){delete value.action;Object.keys(value).length?sessionStorage.setItem(key,JSON.stringify(value)):sessionStorage.removeItem(key)}}catch{}};

const parseInventoryScan=raw=>{const value=String(raw||'').trim();if(!value)return{code:'',attributes:{}};if(value.startsWith('{')){try{const o=JSON.parse(value),code=String(o.serialNumber||o.barcodeValue||o.serial||o.barcode||o.code||o.value||'').trim(),attributes=Object.fromEntries(Object.entries(o).filter(([k])=>!['serialNumber','barcodeValue','serial','barcode','code','value'].includes(k)));return{code,attributes}}catch{}}const parts=value.split('|').map(x=>x.trim()).filter(Boolean),attributes={};for(const part of parts.slice(1)){const i=part.indexOf('=');if(i>0)attributes[part.slice(0,i).trim()]=part.slice(i+1).trim()}return{code:parts[0]||value,attributes}};

function ScanCapture({value,onChange,onScan,placeholder='Scan barcode / QR',compact=false}){const[open,setOpen]=useState(false),[error,setError]=useState(''),[busy,setBusy]=useState(false),videoRef=React.useRef(null);useEffect(()=>{if(!open)return;let stream,stopped=false,raf;const start=async()=>{try{setError('');if(!navigator.mediaDevices?.getUserMedia)throw new Error('Camera access is unavailable. Use a USB/Bluetooth scanner or type the code.');if(!('BarcodeDetector'in window))throw new Error('Camera decoding is unavailable in this browser. Handheld/Bluetooth scanner input still works.');const detector=new window.BarcodeDetector({formats:['qr_code','code_128','code_39','ean_13','ean_8','upc_a','upc_e','data_matrix']});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});if(videoRef.current){videoRef.current.srcObject=stream;await videoRef.current.play()}const tick=async()=>{if(stopped)return;try{const found=await detector.detect(videoRef.current);const raw=found?.[0]?.rawValue;if(raw){stopped=true;setOpen(false);onChange(raw);setBusy(true);await onScan?.(raw);setBusy(false);return}}catch{}raf=requestAnimationFrame(tick)};tick()}catch(e){setError(e.message);setOpen(false)}};start();return()=>{stopped=true;if(raf)cancelAnimationFrame(raf);stream?.getTracks().forEach(t=>t.stop())}},[open]);const submit=async()=>{if(!String(value||'').trim()||busy)return;setBusy(true);try{await onScan?.(value)}finally{setBusy(false)}};return <div className={`smart-scan ${compact?'compact':''}`}><div className="smart-scan-input"><ScanLine size={18}/><input value={value||''} onChange={e=>onChange(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();submit()}}} placeholder={placeholder} autoComplete="off"/><button type="button" className="btn secondary small" disabled={busy} onClick={submit}>{busy?'Reading…':'Use scan'}</button><button type="button" className="btn secondary small" onClick={()=>setOpen(v=>!v)}><Camera size={15}/>{open?'Stop':'Camera'}</button></div>{open&&<video ref={videoRef} className="scanner-video smart-scan-video" playsInline muted/>}{error&&<small className="smart-scan-help error-text">{error}</small>}<small className="smart-scan-help">Camera where supported, or any USB/Bluetooth scanner that types into the field. Structured JSON, GS1 and CODE|key=value payloads preserve extra fields.</small></div>}

async function downloadInventoryTemplate(companyId){const token=localStorage.getItem(tokenKey);const res=await fetch(`${API}${invPath(companyId,'/items/template')}`,{credentials:'include',headers:token?{Authorization:`Bearer ${token}`}:{}});if(!res.ok){const b=await res.json().catch(()=>({}));throw new Error(b.message||'Template download failed.')}const blob=await res.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='opsynq-item-master-template.xlsx';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}

